import React, { useEffect, useState } from 'react';
import { AuthUserPublic, getErrorMessage, updateStudentProfileRequest } from '../api';

interface StudentProfileCardProps {
  user: AuthUserPublic;
  onUserUpdate: (user: AuthUserPublic) => void;
}

export const StudentProfileCard: React.FC<StudentProfileCardProps> = ({ user, onUserUpdate }) => {
  const [editing, setEditing] = useState(false);
  const [classDraft, setClassDraft] = useState(user.className ?? '');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [savedHint, setSavedHint] = useState(false);

  useEffect(() => {
    if (!editing) {
      setClassDraft(user.className ?? '');
    }
  }, [user.className, editing]);

  const handleSave = async () => {
    setSaving(true);
    setError(null);
    try {
      const { user: updated } = await updateStudentProfileRequest(classDraft);
      onUserUpdate(updated);
      setEditing(false);
      setSavedHint(true);
      window.setTimeout(() => setSavedHint(false), 2000);
    } catch (e) {
      setError(getErrorMessage(e));
    } finally {
      setSaving(false);
    }
  };

  const handleCancel = () => {
    setClassDraft(user.className ?? '');
    setEditing(false);
    setError(null);
  };

  return (
    <div className="account-user-card student-profile-card">
      <span className="account-user-avatar">{user.avatar}</span>
      <div className="student-profile-body">
        <strong>{user.displayName}</strong>
        <p className="student-profile-meta">@{user.username} · 咨询记录已绑定账号</p>
        {user.orgName && (
          <p className="student-profile-field">
            <span className="student-profile-label">院系</span>
            <span>{user.orgName}</span>
          </p>
        )}
        <div className="student-profile-field student-profile-class">
          <span className="student-profile-label">班级</span>
          {editing ? (
            <div className="student-profile-edit">
              <input
                type="text"
                className="student-profile-input"
                value={classDraft}
                onChange={(e) => setClassDraft(e.target.value)}
                placeholder="如：软件2301"
                maxLength={32}
                disabled={saving}
              />
              <div className="student-profile-actions">
                <button type="button" className="student-profile-save" onClick={handleSave} disabled={saving}>
                  {saving ? '保存中…' : '保存'}
                </button>
                <button type="button" className="student-profile-cancel" onClick={handleCancel} disabled={saving}>
                  取消
                </button>
              </div>
            </div>
          ) : (
            <div className="student-profile-view">
              <span>{user.className || '未填写'}</span>
              <button type="button" className="student-profile-edit-btn" onClick={() => setEditing(true)}>
                修改
              </button>
            </div>
          )}
        </div>
        {error && <p className="student-profile-error">{error}</p>}
        {savedHint && <p className="student-profile-saved">班级已更新</p>}
      </div>
    </div>
  );
};
